(()=>{const gallery=document.getElementById('device-gallery');if(!gallery)return;const s=Eam.s,eq=new URLSearchParams(location.search).get('equipment')||'EQ-001';let apiAssets=[];let urls=[],renderId=0;
async function render(){const ticket=++renderId;urls.forEach(URL.revokeObjectURL);urls=[];gallery.replaceChildren();const list=document.getElementById('device-documents');list.replaceChildren();gallery.setAttribute('aria-busy','true');list.setAttribute('aria-busy','true');try {const response=await EamArchiveApi.request("GET","/equipment/"+encodeURIComponent(eq)+"/domains/media");if(ticket!==renderId)return;if(response.code===202){gallery.textContent='正在加载设备资料…';list.textContent='正在加载设备资料…';return;}apiAssets=response.data?.items||[];gallery.removeAttribute('aria-busy');list.removeAttribute('aria-busy');}catch(e){if(ticket!==renderId)return;for(const node of [gallery,list]){node.removeAttribute('aria-busy');const alert=document.createElement('div');alert.className='alert alert-warning';alert.setAttribute('role','alert');alert.textContent=e.message;const retry=document.createElement('button');retry.className='btn btn-sm btn-outline-secondary';retry.textContent='重试';retry.onclick=render;node.append(alert,retry);}return;}if(ticket!==renderId)return;const samples=apiAssets.filter(f=>f.category==="image"&&f.previewUrl),docSample=apiAssets.find(f=>f.category==="document"&&f.previewUrl);const images=apiAssets.filter(f=>!f.previewUrl).filter(f=>f.equipmentId===eq&&f.category==='image'&&f.status==='active').sort((a,b)=>Number(!!b.isPrimary)-Number(!!a.isPrimary)),display=images.length?images:(eq==='EQ-001'?samples:[]);Eam.text('gallery-count',images.length?'共 '+images.length+' 张设备图片；点击缩略图放大，方向键可轮播':display.length?'暂无上传图片；显示 '+display.length+' 张可轮播示意图':'暂无设备图片');for(const [i,f]of display.entries()){const card=document.createElement('div');card.className='image-tile';const b=document.createElement('button');b.type='button';b.className='thumbnail-button';b.setAttribute('aria-label','查看图片 '+f.name);const img=document.createElement('img');img.alt=f.name;const caption=document.createElement('span');caption.textContent=f.name+(f.isPrimary?' · 主图':'');b.append(img,caption);b.onclick=()=>EamFileViewer.open(display,i);card.append(b);if(!f.previewUrl){const primary=document.createElement('button');primary.textContent=f.isPrimary?'当前主图':'设为主图';primary.disabled=!!f.isPrimary||!EamProduct.filePermission(s.role,'edit',f);primary.onclick=()=>{if(Eam.run('setPrimaryImage',{id:f.id}))render();};card.append(primary);}gallery.append(card);try{const blob=await EamFiles.get(f);if(ticket!==renderId)return;const u=URL.createObjectURL(blob);urls.push(u);img.src=u;if(i===0)document.querySelector('.device-header img').src=u;}catch{caption.textContent+=' · 内容不可用，请重新关联';}}
const files=apiAssets.filter(f=>!f.previewUrl).filter(f=>f.equipmentId===eq&&f.category!=='image'&&f.status==='active');if(docSample)files.unshift(docSample);for(const f of files){Eam.row(list,f.name+' / '+f.revision,EamProduct.label(f.category)+' / '+(f.previewUrl?'示例内容':f.localContent?'本机内容，未上传':'仅元数据'));const view=document.createElement('button');view.textContent='查看内容';view.onclick=()=>EamFileViewer.open([f]);const download=document.createElement('button');download.textContent='下载原文件';download.disabled=!EamProduct.filePermission(s.role,'download',f);download.title=download.disabled?'需要设备资料下载权限':'';download.onclick=()=>EamFileViewer.download(f);list.lastChild.append(view,download);}if(!files.length)Eam.row(list,'暂无技术资料或模型','通过上传入口维护设备关联文件');}
window.EamArchiveGallery={refresh:render};window.addEventListener('eam-files-changed',()=>{render();window.dispatchEvent(new Event('eam-archive-files-updated'));});window.addEventListener('pagehide',()=>urls.forEach(URL.revokeObjectURL));render();})();
